# -----------------------------
# OpenCV-free helpers (inlined from u7_utils)
# -----------------------------


def _to_float_tensor_img(x: torch.Tensor) -> torch.Tensor:
    """Ensure image tensor is float in [0,1] with shape (C,H,W)."""
    if not torch.is_tensor(x):
        x = torch.as_tensor(x)
    if x.dtype != torch.float32:
        x = x.float()
    # If uint8 [0,255] already converted by ToTensor; but handle raw arrays:
    if x.max() > 1.0:
        x = x / 255.0
    return x

def visualize_filters(filters, ncols: int = 2, image_size: float = 3, cmap="viridis", cmap_dark_to_bright=True):
    """Visualize small 2D filters with numeric values."""
    n_filters = len(filters)
    assert n_filters > 0, "at least one filter must be provided"
    ncols = min(n_filters, ncols)
    nrows = int(np.ceil(n_filters / ncols))
    figsize = (ncols * image_size, nrows * image_size)

    fig, axes = plt.subplots(nrows, ncols, figsize=figsize, squeeze=False)
    ax = axes.flatten()

    vmin = np.asarray(filters).min()
    vmax = np.asarray(filters).max()
    font_color_threshold = vmin + (vmax - vmin) / 2 if vmax > vmin else vmin

    for i in range(n_filters):
        f = np.asarray(filters[i])
        ax[i].imshow(f, cmap=cmap, vmin=vmin, vmax=vmax)
        ax[i].set_xticks([])
        ax[i].set_yticks([])
        for spine in ax[i].spines.values():
            spine.set_edgecolor("black")
        ax[i].set_title(f"Filter {i + 1}")
        width, height = f.shape
        for x in range(width):
            for y in range(height):
                use_white = f[x][y] < font_color_threshold
                if not cmap_dark_to_bright:
                    use_white = not use_white
                ax[i].annotate(f"{f[x][y]:.2f}", xy=(y, x), ha="center", va="center",
                               color="white" if use_white else "black")
    for j in range(i + 1, ax.size):
        ax[j].set_visible(False)

class InitializedNet(torch.nn.Module):
    """Tiny CNN with user-supplied conv filters (weights)."""
    def __init__(self, weights, filter_stride=1, activation=torch.nn.ReLU(), max_pool_size=1):
        super().__init__()
        if isinstance(weights, np.ndarray):
            weights = torch.from_numpy(weights).float()
        if weights.ndim != 4:
            weights = weights.unsqueeze(1)
        assert weights.ndim == 4, "expected weights.shape to be either (N, H, W) or (N, C, H, W)"
        k_n, k_c, k_h, k_w = weights.shape
        self.conv = torch.nn.Conv2d(k_c, k_n, kernel_size=(k_h, k_w), stride=filter_stride, bias=False)
        self.conv.weight = torch.nn.Parameter(weights)
        self.pool = torch.nn.MaxPool2d(kernel_size=max_pool_size)
        self.activation = activation

    def forward(self, x):
        conv_x = self.conv(x)
        activated_x = self.activation(conv_x)
        pooled_x = self.pool(activated_x)
        return conv_x, activated_x, pooled_x

def get_grayscale_image_tensor(image: Union[str, np.ndarray]) -> torch.Tensor:
    """Load image (path or array), convert to grayscale, return tensor shape (1,1,H,W) float."""
    if isinstance(image, str):
        img = plt.imread(image)
    else:
        img = image

    img = np.asarray(img)
    if img.ndim == 2:
        gray = img
    else:
        rgb = img[..., :3]
        gray = 0.2989 * rgb[..., 0] + 0.5870 * rgb[..., 1] + 0.1140 * rgb[..., 2]

    if gray.max() <= 1.0:
        gray = gray * 255.0

    t = torch.from_numpy(gray).unsqueeze(0).unsqueeze(0).float()
    return t

def get_dataset(
    batch_size: int = 20,
    horizontal_flip_p: float = 0.0,
    vertical_flip_p: float = 0.0,
    invert: bool = False,
    valid_size: float = 0.0,
    augment_train: bool = False,
    augment_test: bool = False,
    random_state: int = 42,
    root: str = "resources",
    variant: str = "MNIST",
) -> Tuple[DataLoader, ...]:
    """Return DataLoaders for (train, [valid], test) using torchvision, without OpenCV."""
    assert batch_size >= 1
    assert 0.0 <= horizontal_flip_p <= 1.0
    assert 0.0 <= vertical_flip_p <= 1.0
    assert 0.0 <= valid_size < 1.0
    variant = str(variant)

    # Dataset class + normalization defaults
    if variant == "MNIST":
        ds_cls = torchvision.datasets.MNIST
        mean, std = (0.1307,), (0.3081,)
        is_color = False
        train_kwargs = dict(train=True)
        test_kwargs = dict(train=False)
    elif variant == "FashionMNIST":
        ds_cls = torchvision.datasets.FashionMNIST
        mean, std = (0.2860,), (0.3530,)
        is_color = False
        train_kwargs = dict(train=True)
        test_kwargs = dict(train=False)
    elif variant == "CIFAR10":
        ds_cls = torchvision.datasets.CIFAR10
        mean, std = (0.4914, 0.4822, 0.4465), (0.2470, 0.2435, 0.2616)
        is_color = True
        train_kwargs = dict(train=True)
        test_kwargs = dict(train=False)
    elif variant == "SVHN":
        ds_cls = torchvision.datasets.SVHN
        mean, std = (0.4377, 0.4438, 0.4728), (0.1980, 0.2010, 0.1970)
        is_color = True
        train_kwargs = dict(split="train")
        test_kwargs = dict(split="test")
    elif variant == "USPS":
        ds_cls = torchvision.datasets.USPS
        mean, std = (0.5,), (0.5,)
        is_color = False
        train_kwargs = dict(train=True)
        test_kwargs = dict(train=False)
    else:
        raise ValueError('variant must be one of: MNIST, FashionMNIST, CIFAR10, SVHN, USPS')

    def make_transform(augment: bool) -> T.Compose:
        ops: List[Any] = [T.ToTensor()]
        if invert:
            ops.append(T.Lambda(lambda x: 1.0 - x))
        if augment:
            if horizontal_flip_p > 0:
                ops.append(T.RandomHorizontalFlip(p=float(horizontal_flip_p)))
            if vertical_flip_p > 0:
                ops.append(T.RandomVerticalFlip(p=float(vertical_flip_p)))
        ops.append(T.Normalize(mean=mean, std=std))
        return T.Compose(ops)

    train_tf = make_transform(augment_train and augment_train)
    test_tf  = make_transform(augment_test and augment_test)

    train_ds = ds_cls(root=root, download=True, transform=train_tf, **train_kwargs)
    test_ds  = ds_cls(root=root, download=True, transform=test_tf, **test_kwargs)

    loaders: List[DataLoader] = []

    def _seed_worker(worker_id: int):
        worker_seed = int(random_state) + worker_id
        random.seed(worker_seed)
        np.random.seed(worker_seed)
        torch.manual_seed(worker_seed)

    g = torch.Generator().manual_seed(int(random_state))

    common = dict(
        batch_size=batch_size,
        num_workers=0,
        worker_init_fn=_seed_worker,
        generator=g,
        persistent_workers=False,
    )
    
    if valid_size > 0:
        n_total = len(train_ds)
        n_val = int(round(valid_size * n_total))
        n_train = max(0, n_total - n_val)
        gen = torch.Generator().manual_seed(int(random_state))
        train_sub, val_sub = torch.utils.data.random_split(train_ds, [n_train, n_val], generator=gen)

        loaders.append(DataLoader(train_sub, shuffle=True,  **common))
        loaders.append(DataLoader(val_sub,   shuffle=False, **common))
    else:
        loaders.append(DataLoader(train_ds, shuffle=True, **common))

    loaders.append(DataLoader(test_ds, shuffle=False, **common))
    return tuple(loaders)

