# -----------------------------
# Server logic
# -----------------------------

def server(input, output, session):

    # ---------------- Filters and Convolutions ----------------

    def get_uploaded_image_path(file_input):
        if not file_input:
            return None
        return file_input[0]["datapath"]
    
    def create_filter(filter_type):
        if filter_type == "sobel_x":
            return np.array([[-1, 0, 1], [-2, 0, 2], [-1, 0, 1]])
        elif filter_type == "sobel_y":
            return np.array([[-1, -2, -1], [0, 0, 0], [1, 2, 1]])
        elif filter_type == "edge_detect":
            return np.array([[-1, -1, -1], [-1, 8, -1], [-1, -1, -1]])
        elif filter_type == "blur":
            return np.array([[1, 1, 1], [1, 1, 1], [1, 1, 1]]) / 9
        elif filter_type == "sharpen":
            return np.array([[0, -1, 0], [-1, 5, -1], [0, -1, 0]])
        else:
            # Prefer the JSON coming from the editable table
            j = getattr(input, "custom_filter_json", None)
            if j:
                try:
                    arr = np.array(json.loads(input.custom_filter_json()), dtype=float)
                    if arr.ndim == 2:
                        return arr
                except Exception:
                    pass
            # Fallback (legacy 3x3 numerics in case you keep them around)
            return np.array([
                [getattr(input, "f00", lambda: 0)(), getattr(input, "f01", lambda: 0)(), getattr(input, "f02", lambda: 0)()],
                [getattr(input, "f10", lambda: 0)(), getattr(input, "f11", lambda: 1)(), getattr(input, "f12", lambda: 0)()],
                [getattr(input, "f20", lambda: 0)(), getattr(input, "f21", lambda: 0)(), getattr(input, "f22", lambda: 0)()],
            ], dtype=float)

        
    
    @output
    @render.plot
    #@reactive.event(input.apply_filter)
    def filter_viz():
        if input.apply_filter() == 0:
            plt.text(0.5, 0.5, "Apply a filter to see its visualization", ha="center")
            plt.grid(False)
            plt.axis('off')
            return plt.gcf()
        filter_matrix = create_filter(input.filter_type())
        visualize_filters([filter_matrix])
        return plt.gcf()
    
    
    
    @output
    @render.plot
    #@reactive.event(input.apply_filter)
    def convolution_result():
        img_path = get_uploaded_image_path(input.conv_image())
        if not img_path or input.apply_filter() == 0:
            plt.text(0.5, 0.5, "Upload an image to see convolution result", ha="center")
            plt.grid(False)
            plt.axis('off')
            return plt.gcf()
        
        # Load and convert image
        image = plt.imread(img_path)
        # convert to grayscale (no OpenCV)
        if image.ndim == 3:
            rgb = image[..., :3]
            image = 0.2989 * rgb[..., 0] + 0.5870 * rgb[..., 1] + 0.1140 * rgb[..., 2]
        
        # Apply filter
        filter_matrix = create_filter(input.filter_type())

        fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(10, 4))

        # --- compute convolution ---
        filtered = correlate2d(image, filter_matrix, mode="same", boundary="symm")

        # --- normalize ---
        img = np.asarray(image, dtype=float)

        if img.max() > 1.0:
            img01 = img / 255.0
            filt01 = filtered / 255.0
        else:
            img01 = img
            filt01 = filtered

        # --- display logic ---
        if input.filter_type() in ("sharpen", "blur"):
            filt_show = np.clip(filt01, 0.0, 1.0)
        else:
            f = filt01
            f = (f - f.min()) / (f.max() - f.min() + 1e-9)
            filt_show = f

        ax1.imshow(img01, cmap="gray", vmin=0, vmax=1)
        ax1.set_title("Original")

        ax2.imshow(filt_show, cmap="gray", vmin=0, vmax=1)
        ax2.set_title("After " + input.filter_type().replace("_", " ").title())

        ax1.axis("off")
        ax2.axis("off")

        return fig
    

    @render.ui
    def custom_filter_df():
        
        # Re-render when the size changes
        # k = int(input.custom_size() or 3)

        # NEW: now just set to 3x3
        k = 3

        # Default to center-1, others 0 (you can change this)
        df = pd.DataFrame(np.zeros((k, k), dtype=float))
        df.iloc[k // 2, k // 2] = 1.0

        # Build an HTML table we can make contenteditable
        html = df.to_html(
            index=False, header=False,
            table_id="custom-filter-table",
            classes="dataframe shiny-table"
        )

        # JS: make cells editable and push JSON -> input.custom_filter_json
        script = """
        <script>
        (function(){
        function init(){
            const table = document.getElementById('custom-filter-table');
            if(!table) return false;

            function pushTable(){
            const rows = Array.from(table.querySelectorAll('tr'));
            const data = rows.map(tr =>
                Array.from(tr.querySelectorAll('td')).map(td => {
                const v = parseFloat(td.textContent.trim());
                return isNaN(v) ? 0 : v;
                })
            );
            Shiny.setInputValue('custom_filter_json', JSON.stringify(data), {priority: 'event'});
            }

            // Make each cell editable and wire events
            Array.from(table.querySelectorAll('td')).forEach(td => {
            td.setAttribute('contenteditable','true');
            td.addEventListener('input', pushTable);
            td.addEventListener('blur', pushTable);
            });

            // Prime the value once at init
            pushTable();
            return true;
        }
        // try init now and also after Shiny reconnects
        document.addEventListener('DOMContentLoaded', init);
        document.addEventListener('shiny:connected', init);
        setTimeout(init, 50);
        })();
        </script>
        """

        return ui.HTML(html + script)


    # ---------- Basics: CNN Building Blocks ----------

    # Current kernel used by Apply (updated from edits or preset)
    bb_kernel_state = reactive.Value(None)

    #  Matrix used to RENDER the HTML table (only changed on size change / preset)
    bb_render_matrix = reactive.Value(None)

    # Bump this to force the table to re-render
    bb_table_version = reactive.Value(0)

    @reactive.effect
    @reactive.event(input.bb_size)
    def _bb_on_size_change():
        k = int(input.bb_size() or 4)
        M = np.zeros((k, k), dtype=float)
        M[k // 2, k // 2] = 1.0
        bb_render_matrix.set(M)
        bb_table_version.set(bb_table_version() + 1)

    @render.ui
    def bb_kernel_views():
        # Use the same source the Apply button uses
        K = bb_kernel_state()
        if not (isinstance(K, np.ndarray) and K.ndim == 2 and K.shape[0] == K.shape[1]):
            # fall back to current size with center-1 if state is not ready
            k = int(input.bb_size() or 4)
            K = np.zeros((k, k), dtype=float)
            K[k // 2, k // 2] = 1.0

        K = K.astype(float)
        kneg  = -K
        kt    = K.T
        ktneg = -kt

        # helper to a small, tight table (read-only)
        def _tbl(arr: np.ndarray, table_id: str) -> str:
            df = pd.DataFrame(arr)
            return df.to_html(index=False, header=False, table_id=table_id, classes="dataframe shiny-table")

        html = []
        html.append("<div style='display:flex; flex-direction:column; gap:12px;'>")
        html.append("<div><strong>-K</strong>")
        html.append(_tbl(kneg,  "bb-kneg"))
        html.append("</div>")
        html.append("<div><strong>K<sup>T</sup></strong>")
        html.append(_tbl(kt,    "bb-kt"))
        html.append("</div>")
        html.append("<div><strong>-K<sup>T</sup></strong>")
        html.append(_tbl(ktneg, "bb-ktneg"))
        html.append("</div>")
        html.append("</div>")

        return ui.HTML("".join(html))

    def _bb_default_matrix_for_size(k: int) -> np.ndarray:
        M = np.zeros((k, k), dtype=float)
        M[k // 2, k // 2] = 1.0
        return M

    def _bb_current_kernel_or_default() -> np.ndarray:
        K = bb_kernel_state()
        k = int(input.bb_size() or 4)
        if isinstance(K, np.ndarray) and K.ndim == 2 and K.shape == (k, k):
            return K.astype(float)
        return _bb_default_matrix_for_size(k).astype(float)

    def _bb_table_html(arr: np.ndarray, table_id: str) -> str:
        df = pd.DataFrame(arr)
        return df.to_html(index=False, header=False, table_id=table_id, classes="dataframe shiny-table")


