    @reactive.calc
    @reactive.event(input.load_data, input.start_train)
    def loaders():
        with reactive.isolate():
            batch_size = int(input.batch())
            variant    = str(input.variant())
            valid_frac = float(input.valid())
            seed       = int(input.seed() or 0)
            use_official = bool(input.use_official_test())

            # Load base (no built-in valid split; we’ll split ourselves consistently)
            base = get_dataset(
                batch_size=batch_size,
                horizontal_flip_p=float(input.hflip()),
                vertical_flip_p=float(input.vflip()),
                invert=bool(input.invert()),
                valid_size=0.0,      # do our own split
                augment_train=bool(input.augment()),
                augment_test=False,  # never augment test
                variant=variant,
                random_state=seed,
            )
            if len(base) == 2:
                base_train_loader, base_test_loader = base
            else:
                base_train_loader, _, base_test_loader = base

            rng = np.random.RandomState(seed)

            def _seed_worker(worker_id: int):
                    # Make worker-level RNG deterministic (important if num_workers > 0 later)
                    worker_seed = seed + worker_id
                    random.seed(worker_seed)
                    np.random.seed(worker_seed)
                    torch.manual_seed(worker_seed)

            g = torch.Generator()
            g.manual_seed(seed)

            common = dict(
                batch_size=batch_size,
                num_workers=0,            # keep deterministic
                worker_init_fn=_seed_worker,
                generator=g,              # use the same generator everywhere
                persistent_workers=False,
            )


            if use_official:
                # -------- Mode A: keep official test set; split TRAIN -> train/val --------
                train_ds = base_train_loader.dataset
                N = len(train_ds)
                n_val = int(round(valid_frac * N))
                n_train = max(0, N - n_val)

                idx = np.arange(N); rng.shuffle(idx)
                train_idx = idx[:n_train]
                val_idx   = idx[n_train:]

                ds_train = Subset(train_ds, train_idx.tolist())
                ds_valid = Subset(train_ds, val_idx.tolist()) if n_val > 0 else Subset(train_ds, [])
                ds_test  = base_test_loader.dataset  # official test

                dl_train = DataLoader(ds_train, shuffle=True,  **common)
                dl_valid = DataLoader(ds_valid, shuffle=False, **common)
                dl_test  = DataLoader(ds_test,  shuffle=False, **common)
                return (dl_train, dl_valid, dl_test)

            else:
                # -------- Mode B: custom split on pool (TRAIN ∪ official TEST) --------
                # Only now do we read input.test(); provide a safe default if absent.
                test_frac = float(getattr(input, "test", lambda: 0.1)() or 0.1)

                pool = ConcatDataset([base_train_loader.dataset, base_test_loader.dataset])
                N = len(pool)

                # Guard rails: keep some train left
                valid = max(0.0, min(0.8, valid_frac))
                test  = max(0.0, min(0.8, test_frac))
                if valid + test > 0.95:
                    scale = 0.95 / (valid + test)
                    valid *= scale; test *= scale

                n_valid = int(round(valid * N))
                n_test  = int(round(test  * N))
                n_train = max(0, N - n_valid - n_test)

                idx = np.arange(N); rng.shuffle(idx)
                train_idx = idx[:n_train]
                valid_idx = idx[n_train:n_train+n_valid]
                test_idx  = idx[n_train+n_valid:]

                ds_train = Subset(pool, train_idx.tolist())
                ds_valid = Subset(pool, valid_idx.tolist()) if n_valid > 0 else Subset(pool, [])
                ds_test  = Subset(pool, test_idx.tolist())  if n_test  > 0 else Subset(pool, [])

                dl_train = DataLoader(ds_train, shuffle=True,  **common)
                dl_valid = DataLoader(ds_valid, shuffle=False, **common)
                dl_test  = DataLoader(ds_test,  shuffle=False, **common)
                return (dl_train, dl_valid, dl_test)

