    @render.text
    @reactive.event(input.load_data)
    def data_info():
        # Depend on loaders()
        train_loader, val_loader, test_loader = loaders()

        n_train = len(train_loader.dataset)
        n_val   = len(val_loader.dataset)
        n_test  = len(test_loader.dataset)

        # Peek input shape safely
        try:
            x0, _ = test_loader.dataset[0]  # test has no shuffle; augment_test is False in your setup
            if isinstance(x0, torch.Tensor):
                shape = tuple(x0.shape)
            else:
                shape = tuple(np.asarray(x0).shape)
        except Exception:
            shape = ("?", "?", "?")

        total = max(1, n_train + n_val + n_test)
        p = lambda n: f"{(n/total):.0%}"
        mode = "official test" if bool(input.use_official_test()) else "custom split"

        # Class names from train set (typical source of truth)
        names = _class_names_from_variant(input.variant())
        if names is None:
        # If you later switch to datasets that keep .classes, keep these two tries:
            names = _class_names_from_dataset(train_loader.dataset) or _class_names_from_dataset(test_loader.dataset)
        if names is None:
            names = _fallback_numeric_class_names(train_loader) or _fallback_numeric_class_names(test_loader)

        lines = [
            f"Loaded {input.variant()} dataset.\n",
            f"training set:   {n_train} ({p(n_train)}),",
            f"validation set: {n_val} ({p(n_val)}),",
            f"test set:       {n_test} ({p(n_test)}) [{mode}].",
            f"\nInput shape: {shape}\n"
        ]

        if names:
            lines.append("Class labels:")
            lines.extend(f"{i}: {n}" for i, n in enumerate(names))
            lines.append("")  # trailing newline

        return "\n".join(lines)



