    @render.table
    def arch_table():
        txt = arch_state()
        try:
            specs = parse_architecture(txt)
        except Exception as e:
            return pd.DataFrame({"error":[str(e)]})
        if not specs:
            return pd.DataFrame()  # no table if empty
        rows = []
        for i, sp in enumerate(specs):
            row = {"#": i, "type": sp.type}
            row.update({k: json.dumps(v) if isinstance(v,(list,dict)) else v for k,v in sp.params.items()})
            rows.append(row)
        return pd.DataFrame(rows).replace({np.nan: ""})
        
