    # ---------------- Training (non-blocking) ----------------

    # Thread->UI message queue
    _train_q: "queue.SimpleQueue[dict]" = queue.SimpleQueue()

    def _q_put(msg: dict):
        """Thread-safe enqueue (SimpleQueue is safe for threads)."""
        _train_q.put(msg)

    _training_context = isolated_training.Executor(7)
    session.on_ended(_training_context.cancel)

    def run_training_sync(params: dict) -> dict:
        """
        Runs the whole training synchronously (CPU/GPU), but DOES NOT touch Shiny reactives directly.
        Reports progress via _q_put().
        Returns result dict consumed on main thread.
        """
        import random

        seed       = int(params["seed"])
        epochs     = int(params["epochs"])
        lr         = float(params["lr"])
        momentum   = float(params["momentum"])
        use_es     = bool(params["use_es"])
        patience   = int(params["es_patience"])
        use_cuda   = bool(params["use_cuda"])
        specs_text = params["arch_text"]
        train_loader, val_loader, test_loader = params["loaders"]

        # Reproducibility
        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        if torch.cuda.is_available():
            torch.cuda.manual_seed_all(seed)

        # Stronger CPU determinism
        torch.set_num_threads(1)
        try:
            torch.backends.mkldnn.enabled = False  # avoids some nondeterministic CPU conv paths
        except Exception:
            pass

        # Determinism (good to keep)
        torch.use_deterministic_algorithms(True)
        if torch.cuda.is_available():
            torch.backends.cudnn.deterministic = True
            torch.backends.cudnn.benchmark = False

        device = torch.device("cuda" if (torch.cuda.is_available() and use_cuda) else "cpu")

        # Build model
        specs = parse_architecture(specs_text)

        # Create a deterministic peek loader (no shuffle) to infer shapes/labels
        peek_loader = DataLoader(
            train_loader.dataset,
            batch_size=train_loader.batch_size,
            shuffle=False,
            num_workers=0,
        )


        x0, y0 = next(iter(peek_loader))
        input_shape = tuple(x0.shape[1:])
        model = build_model(specs, input_shape).to(device)

        # Infer classes
        with torch.no_grad():
            logits = model(x0[:2].to(device))
        #y0 = next(iter(train_loader))[1]
        n_classes = int(torch.max(y0).item()) + 1 if y0.dtype in (torch.int64, torch.int32, torch.int16, torch.uint8) else None

        # Loss
        # (Keep your original logic: classification if labels are int-like; else regression)
        is_classification = (y0.dtype in (torch.int64, torch.int32, torch.int16, torch.uint8))
        if is_classification:
            loss_fn = nn.CrossEntropyLoss()
        else:
            loss_fn = nn.MSELoss()

        optimizer = torch.optim.SGD(model.parameters(), lr=lr, momentum=momentum)

        # Early stopping bookkeeping
        best_state = None
        best_epoch = None
        best_val = float("inf")
        bad = 0

        # filter history (first conv weights per epoch)
        hist = []
        w0 = get_first_conv_weights(model)
        if w0 is not None:
            hist.append(w0.copy())

        hist_rows = []
        val_available = (val_loader is not None)

        # progress init
        _q_put({"type": "progress", "pct": 0, "msg": "Initializing…"})
        _q_put({"type": "best_info", "text": ""})
        _q_put({"type": "history_reset"})
        _q_put({"type": "filters_reset"})

        for ep in range(epochs):
           
            random.seed(seed + ep)
            np.random.seed(seed + ep)
            torch.manual_seed(seed + ep)
            if torch.cuda.is_available():
                torch.cuda.manual_seed_all(seed + ep)

            model.train()

            running = 0.0
            n = 0

            total_batches = len(train_loader) if hasattr(train_loader, "__len__") else 1
            UPDATE_EVERY = 20  # you said you already throttled; keep this moderate

            for b_idx, (xb, yb) in enumerate(train_loader, start=1):
                xb = xb.to(device)
                yb = yb.to(device)

                optimizer.zero_grad(set_to_none=True)
                out = model(xb)
                loss = loss_fn(out, yb)
                loss.backward()
                optimizer.step()

                running += float(loss.item()) * int(xb.size(0))
                n += int(xb.size(0))

                if (b_idx % UPDATE_EVERY == 0) or (b_idx == total_batches):
                    pct = int(((ep * total_batches + b_idx) / max(1, (epochs * total_batches))) * 100)
                    _q_put({
                        "type": "progress",
                        "pct": pct,
                        "msg": f"Epoch {ep+1}/{epochs} — batch {b_idx}/{total_batches} — loss {loss.item():.3f}"
                    })

            train_loss = running / max(1, n)

            # Validation
            val_loss = None
            if val_available:
                model.eval()
                tot = 0.0
                nval = 0
                with torch.no_grad():
                    for xv, yv in val_loader:
                        xv = xv.to(device)
                        yv = yv.to(device)
                        ov = model(xv)
                        lv = loss_fn(ov, yv)
                        tot += float(lv.item()) * int(xv.size(0))
                        nval += int(xv.size(0))
                val_loss = tot / max(1, nval)

            # Save filters per epoch (optional; you already limit UI size)
            w = get_first_conv_weights(model)
            if w is not None:
                hist.append(w.copy())
                _q_put({"type": "filters_append", "weights": w.copy()})

            # Record history row
            row = {"train": float(train_loss)}
            if val_loss is not None:
                row["val"] = float(val_loss)
            hist_rows.append(row)
            _q_put({"type": "history_append", "row": row})

            # Early stopping check
            if use_es and (val_loss is not None):
                if val_loss < best_val - 1e-12:
                    best_val = val_loss
                    best_epoch = ep + 1
                    best_state = copy.deepcopy(model.state_dict())
                    bad = 0
                    _q_put({"type": "best_info", "text": f"New best model @ epoch {best_epoch} (val={best_val:.4f})"})
                else:
                    bad += 1
                    if bad >= patience:
                        _q_put({"type": "progress", "pct": int(((ep+1)/epochs)*100), "msg": f"Early stopping @ epoch {ep+1}"})
                        break

        # finalize: choose model
        used = "last"
        if use_es and best_state is not None:
            model.load_state_dict(best_state)
            used = "best"

        # best info string
        last_ep = len(hist_rows)
        if used == "best":
            best_info = f"Using best model (epoch {best_epoch}, best val={best_val:.4f})"
        else:
            val_part = ""
            if ("val" in hist_rows[-1]):
                val_part = f", val={hist_rows[-1]['val']:.4f}"
            best_info = f"Using last epoch model (epoch {last_ep}, train={hist_rows[-1]['train']:.4f}{val_part})"

        # build DataFrame for output
        df = pd.DataFrame(hist_rows)

        # Done
        _q_put({"type": "progress", "pct": 100, "msg": "Training complete"})
        return {
            "model": model.to("cpu"),
            "history_df": df,
            "filters": hist,
            "best_info": best_info
        }


    @reactive.extended_task
    async def train_task(params: dict):
        # Run the sync training in a worker thread so Shiny's event loop stays responsive
        result = await _training_context.run(params, _q_put)
        result["model"] = isolated_training.restore_model(result.pop("model_record"), build_model, parse_architecture(params["arch_text"]))
        return result


    @reactive.effect
    @reactive.event(input.start_train)
    def _start_train_task():
        _training_context.cancel()
        train_task.cancel()
        while not _train_q.empty():
            _train_q.get_nowait()
        # reset UI immediately (main thread)
        train_progress_pct.set(0)
        train_progress_msg.set("Initializing…")
        best_model_info.set("")
        train_history.set(pd.DataFrame())
        filter_history.set([])
        trained_model.set(None)

        # capture current params safely
        with reactive.isolate():
            params = {
                "seed": int(input.seed() or 0),
                "epochs": int(input.epochs() or 1),
                "lr": float(input.lr() or 0.01),
                "momentum": float(input.momentum() or 0.0),
                "use_es": bool(input.use_es()),
                "es_patience": int(input.es_patience() or 5),
                "use_cuda": bool(input.use_cuda()),
                "arch_text": arch_state(),
                "loaders": loaders(),   # IMPORTANT: build loaders on main thread
            }

        # kick off background job
        train_task.invoke(params)


    @reactive.effect
    def _pump_training_messages():
        # poll queue regularly
        reactive.invalidate_later(0.1)

        while True:
            try:
                msg = _train_q.get_nowait()
            except queue.Empty:
                break

            t = msg.get("type")

            if t == "progress":
                train_progress_pct.set(int(msg["pct"]))
                train_progress_msg.set(str(msg["msg"]))

            elif t == "best_info":
                best_model_info.set(str(msg["text"]))

            elif t == "history_reset":
                train_history.set(pd.DataFrame())

            elif t == "history_append":
                row = msg["row"]
                df = train_history()
                if df is None or df.empty:
                    df2 = pd.DataFrame([row])
                else:
                    df2 = pd.concat([df, pd.DataFrame([row])], ignore_index=True)
                train_history.set(df2)

            elif t == "filters_reset":
                filter_history.set([])

            elif t == "filters_append":
                hist = filter_history() or []
                hist.append(msg["weights"])
                filter_history.set(hist)


    @reactive.effect
    def _finalize_training_task():
        # when task completes, apply final results on main thread
        if train_task.status() != "success":
            if train_task.status() == "error":
                # show error cleanly in UI
                err = str(train_task.error())
                train_history.set(pd.DataFrame({"error": [err]}))
                trained_model.set(None)
                best_model_info.set(f"Error: {err}")
                train_progress_msg.set(f"Error: {err}")
                train_progress_pct.set(0)
            return

        res = train_task.result()
        trained_model.set(res["model"])
        #train_history.set(res["history_df"])
        best_model_info.set(res["best_info"])

        # finalize filters & slider safely on main thread
        hist = res["filters"]
        filter_history.set(hist)
        try:
            ui.update_slider("filter_epoch", min=0, max=max(0, len(hist) - 1), value=max(0, len(hist) - 1))
        except Exception:
            pass

        train_progress_msg.set("Training complete")
        train_progress_pct.set(100)




