            with torch.no_grad():
                A = partial(x0)  # x0 is your 1×C×H×W tensor built earlier

            layer_name = children[child_idx].__class__.__name__

            if A.ndim == 4:
                A = A[0]
                n = min(n_show, A.shape[0])
                cols = max(1, int(math.sqrt(n))); rows = math.ceil(n/cols)
                idx = 0
