    # ---------------- Analysis ----------------
    def _compute_confusion_matrix(model: nn.Module, loader, n_classes: int) -> np.ndarray:
        model.eval()
        cm = np.zeros((n_classes, n_classes), dtype=np.int64)
        with torch.no_grad():
            for xb, yb in loader:
                logits = model(xb)
                pred = logits.argmax(dim=1).cpu().numpy()
                true = yb.cpu().numpy()
                for t, p in zip(true, pred):
                    cm[t, p] += 1
        return cm

    def _precision_recall_f1(cm: np.ndarray) -> Tuple[Dict[str,float], Dict[int,Tuple[float,float,float]]]:
        # per-class
        eps = 1e-12
        tp = np.diag(cm).astype(float)
        fp = cm.sum(axis=0).astype(float) - tp
        fn = cm.sum(axis=1).astype(float) - tp
        precision = (tp / (tp + fp + eps))
        recall = (tp / (tp + fn + eps))
        f1 = (2*precision*recall) / (precision + recall + eps)
        per_class = {i: (precision[i], recall[i], f1[i]) for i in range(len(tp))}
        # micro
        tp_sum = tp.sum(); fp_sum = fp.sum(); fn_sum = fn.sum()
        prec_micro = tp_sum / (tp_sum + fp_sum + eps)
        rec_micro = tp_sum / (tp_sum + fn_sum + eps)
        f1_micro = (2*prec_micro*rec_micro) / (prec_micro + rec_micro + eps)
        # macro
        prec_macro = float(np.mean(precision))
        rec_macro = float(np.mean(recall))
        f1_macro = float(np.mean(f1))
        # weighted
        support = cm.sum(axis=1).astype(float)
        w = support / (support.sum() + eps)
        prec_weighted = float(np.sum(w * precision))
        rec_weighted = float(np.sum(w * recall))
        f1_weighted = float(np.sum(w * f1))
        summary = {
            'micro_precision': float(prec_micro), 'micro_recall': float(rec_micro), 'micro_f1': float(f1_micro),
            'macro_precision': prec_macro, 'macro_recall': rec_macro, 'macro_f1': f1_macro,
            'weighted_precision': prec_weighted, 'weighted_recall': rec_weighted, 'weighted_f1': f1_weighted,
        }
        return summary, per_class

    @render.plot
    @reactive.event(input.compute_analysis)
    def confusion_plot():
        input.compute_analysis()
        model = trained_model()
        fig = plt.figure()
        if model is None:
            plt.text(0.5, 0.5, "Train a model first", ha="center")
            plt.axis('off')
            return fig
        L = loaders()
        test_loader = L[-1]
        ys = next(iter(test_loader))[1]
        n_classes = int(ys.max().item() + 1)
        cm = _compute_confusion_matrix(model, test_loader, n_classes)

        normalize = bool(input.cm_normalize())
        if normalize:
            with np.errstate(divide='ignore', invalid='ignore'):
                cm_plot = cm / cm.sum(axis=1, keepdims=True)
                cm_plot = np.nan_to_num(cm_plot)
            fmt = ".2f"
        else:
            cm_plot = cm  # keep as int for %d formatting
            fmt = "d"

        im = plt.imshow(cm_plot, cmap="YlGn")  # perceptually uniform, dark background
        plt.xlabel("Predicted")
        plt.ylabel("True")
        plt.title("Confusion Matrix of Test Set Predictions")
        plt.colorbar(im)

        # text color threshold using normalized intensity
        denom = cm_plot.max() if not normalize else 1.0
        nrows, ncols = cm_plot.shape
        for i in range(nrows):
            for j in range(ncols):
                val = cm_plot[i, j]
                txt = format(val, fmt)
                intensity = (val / denom) if denom else 0.0
                color = "white" if intensity > 0.5 else "black"
                plt.text(j, i, txt, ha="center", va="center", color=color)
        plt.tight_layout()
        return fig


    @render.text
    @reactive.event(input.compute_analysis)
    def metrics_text():
        model = trained_model()
        if model is None:
            return "Train a model first"
        L = loaders()
        test_loader = L[-1]
        ys = next(iter(test_loader))[1]
        n_classes = int(ys.max().item() + 1)
        cm = _compute_confusion_matrix(model, test_loader, n_classes)
        view = str(input.metric_view())
        total = cm.sum(); correct = cm.trace()
        if view == 'acc':
            overall = correct / max(1, total)
            per_class = []
            for i in range(n_classes):
                denom = cm[i].sum()
                acc = (cm[i, i] / denom) if denom > 0 else 0.0
                per_class.append((i, acc))
            lines = [f"Overall accuracy on test data: {overall:.3f}"] + [f"Class {i}: {acc:.3f}" for i, acc in per_class]
            return "\n".join(lines)
        else:
            summary, per_cls = _precision_recall_f1(cm)
            if view == 'prf_micro':
                return (f"Micro Precision: {summary['micro_precision']:.3f}\n"
                        f"Micro Recall: {summary['micro_recall']:.3f}\n"
                        f"Micro F1: {summary['micro_f1']:.3f}")
            if view == 'prf_macro':
                return (f"Macro Precision: {summary['macro_precision']:.3f}\n"
                        f"Macro Recall: {summary['macro_recall']:.3f}\n"
                        f"Macro F1: {summary['macro_f1']:.3f}")
            if view == 'prf_weighted':
                return (f"Weighted Precision: {summary['weighted_precision']:.3f}\n"
                        f"Weighted Recall: {summary['weighted_recall']:.3f}\n"
                        f"Weighted F1: {summary['weighted_f1']:.3f}")
            # fallback
            return "Unknown metric view"





